(function(){'use strict';const root=document.getElementById('graph-app'),C=WILCore;let current=0,variant='',history=[];const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function view(id,gateId=''){const n=C.node(Number(id));current=n.id;variant=gateId;const route=n.conditionalRoutes?.find(g=>g.id===gateId),definition=C.GATES.find(g=>g.id===gateId);const active=definition&&route?definition.scene:n;const edges=route?definition.scene.options.map((o,i)=>({text:o.text,feedback:o.reply,effect:o.effect,to:route.targets[i],terminal:n.state.stage===79})):n.choices;const text=active.text||n.summary?.join(' ')||'';root.innerHTML=`<div class="game-layout"><h1>Decision Graph · ${n.id}</h1><p>กราฟสถานะของเรื่อง มีทางเลือกหลักและทางแยกที่เปิดด้วยค่าพลัง ทุกภาพสร้างจากรายละเอียดฉากของโหนดนั้น</p><div class="graph-controls"><input id="node-id" type="number" min="0" max="${C.STORY_NODES+C.LEAVES-1}" value="${n.id}" aria-label="หมายเลขโหนด"><button class="primary" onclick="StoryMap.open()">เปิดโหนด</button><button class="secondary" onclick="StoryMap.back()">ย้อนทางที่เปิด</button><a class="secondary" href="storygraph/nodes.jsonl.gz" download>ดาวน์โหลดโหนดทั้งหมด</a><a class="secondary" href="storygraph/manifest.json">Manifest</a></div><p id="graph-error" role="alert"></p>${n.kind==='scene'?`<label for="gate-choice">เส้นทางตามเงื่อนไข</label><select id="gate-choice" onchange="StoryMap.variant(this.value)"><option value="">เรื่องหลัก</option>${n.conditionalRoutes.map(g=>`<option value="${g.id}" ${gateId===g.id?'selected':''}>${e(g.id)} · ${e(g.when)}</option>`).join('')}</select>`:''}<div class="scene-stage"><canvas id="graph-scene" role="img" aria-label="ภาพเฉพาะโหนด ${n.id}"></canvas></div><h2>${e(active.title)}</h2><p>${e(text)}</p>${definition&&route?`<div class="game-banner">เงื่อนไขเปิด: ${e(definition.when)}${definition.once?' · ครั้งเดียวต่อรอบ':''}</div>`:''}<svg class="local-tree" viewBox="0 0 800 180" role="img" aria-label="แผนผังทางเลือกจากโหนดปัจจุบัน"><rect x="300" y="8" width="200" height="42" rx="6" fill="#30586b"/><text x="400" y="35" text-anchor="middle" fill="#f5df9d">NODE ${n.id}</text>${edges.map((o,i)=>{const x=100+i*200;return`<path d="M400 50 L${x} 125" stroke="#7ddbb9" fill="none"/><a href="?node=${o.to}"><rect x="${x-85}" y="125" width="170" height="40" rx="4" fill="#243e51" stroke="#78baab"/><text x="${x}" y="151" text-anchor="middle" fill="#e2edda">${'ABCD'[i]} → ${o.to}</text></a>`}).join('')}</svg><div class="graph-edges">${edges.map((o,i)=>`<button onclick="StoryMap.step(${o.to})"><b>${'ABCD'[i]} · ${e(o.text)}</b><p>${e(o.feedback)}</p><code>→ Node ${o.to}</code><p>${e(JSON.stringify(o.effect))}</p>${o.terminal?'<small>ปลายเรื่องใช้เกณฑ์ประเมินประวัติจริงเลือกฉากจบ ตัวเลขนี้เป็น Leaf ตัวแทนสำหรับดูโครงสร้าง</small>':''}</button>`).join('')}</div><details><summary>ข้อมูลโหนดและเงื่อนไขทั้งหมด</summary><pre style="white-space:pre-wrap">${e(JSON.stringify(n,null,2))}</pre></details></div>`;const location=definition&&route?active.location:n.location||n.scene.split(':')[0],eventId=gateId?`gate:${gateId}`:n.eventId||active.id,artKey=gateId?active.id:n.artKey||active.id,eventSeed=C.hash(n.id+String(eventId).split('').reduce((a,c)=>a+c.charCodeAt(0),0)+String(artKey).split('').reduce((a,c)=>a+c.charCodeAt(0),0));WILArt.draw(document.getElementById('graph-scene'),{location,chain:n.state?.chain||0,energy:n.state?.pressure?25:75,mood:n.kind==='ending'?(n.tier>=3?'happy':n.tier===0?'tired':'neutral'):n.state.team<2?'angry':n.state.team>2?'happy':'neutral',tier:n.tier||0,seed:eventSeed,event:gateId||active.id,eventId,category:gateId?'gate':n.category||'legacy',artKey,props:gateId?(active.props||[]):n.props||[],actor:gateId?(active.actor||null):n.actor||null,emotion:gateId?(active.emotion||'neutral'):n.emotion||'neutral'},{avatarGender:'male',avatarHair:2,avatarHairColor:0})}
window.StoryMap={open(){try{view(document.getElementById('node-id').value)}catch(err){document.getElementById('graph-error').textContent=err.message}},variant(id){view(current,id)},step(id){history.push({id:current,variant});view(id)},back(){if(history.length){const p=history.pop();view(p.id,p.variant)}}};try{view(new URLSearchParams(location.search).get('node')||0)}catch(err){root.textContent=err.message}
})();
